  "Per le condizioni giuridiche e commerciali complete consulta i documenti pubblicati nel footer. Per un problema relativo a uno specifico ordine, verifica prima le informazioni del Venditore e dell'ordine.": "Pour connaître l'intégralité des conditions juridiques et commerciales, consultez les documents publiés en pied de page. Pour un problème lié à une commande spécifique, vérifiez d'abord le vendeur et les informations de commande.",
  "Guida locale": "Guide local",
  "La città": "La ville",
  "Identità locale": "Identité locale",
  "Castrovillari vive tutto l'anno attraverso teatro, musica, folklore, libri, arte e iniziative di comunità. Il calendario cambia di anno in anno: per date confermate e programmi completi fai riferimento agli organizzatori.": "Castrovillari vit toute l'année à travers le théâtre, la musique, le folklore, les livres, l'art et les initiatives communautaires. Le calendrier change d'année en année : pour les dates confirmées et les programmes complets merci de vous référer aux organisateurs.",
  "Da non perdere": "A ne pas manquer",
  "Gusto e territorio": "Goût et territoire",
  "Scopri le tradizioni gastronomiche di Castrovillari e del Pollino, compresa la Cipolla Bianca di Castrovillari, riconosciuta De.Co. Per produttori, stagionalità e iniziative enogastronomiche consulta le fonti locali e gli eventi in programma.": "Découvrez les traditions gastronomiques de Castrovillari et Pollino, dont l'oignon blanc de Castrovillari, reconnu par De.Co. Pour les producteurs, la saisonnalité et les initiatives gastronomiques et œnologiques, consultez les sources locales et les événements programmés.",
