  "Il tuo riepilogo personale: ordini, preferiti, offerte ed eventi.": "Votre récapitulatif personnel : commandes, favoris, offres et événements.",
  "Il riepilogo della tua attività su Radici Calabria: ordini, preferiti e ultimi acquisti, sempre a portata di mano.": "Le résumé de votre activité sur Radici Calabria : commandes, favoris et derniers achats, toujours à portée de main.",
  "Storico dei tuoi ordini con lo stato di spedizione e consegna.": "Historique de vos commandes avec statut d'expédition et de livraison.",
  "Lo storico completo dei tuoi acquisti, salvato sul tuo account: ritorna quando vuoi e ritrova ogni ordine con il suo stato.": "L'historique complet de vos achats, enregistré dans votre compte : revenez quand vous le souhaitez et retrouvez chaque commande avec son statut.",
  "Negozi e prodotti salvati per non perderli di vista.": "Magasins et produits enregistrés pour ne pas les perdre de vue.",
