  "Hai un account? I tuoi ordini restano qui per sempre.": "Avez-vous un compte ? Vos commandes restent ici pour toujours.",
  "I tuoi ordini restano al sicuro: servono entrambi i dati per trovarli": "Vos commandes restent en sécurité : vous avez besoin des deux données pour les retrouver",
  "Puoi recuperare i tuoi ordini in qualsiasi momento inserendo email e telefono usati al checkout.": "Vous pouvez récupérer vos commandes à tout moment en saisissant l'e-mail et le numéro de téléphone utilisés lors du paiement.",
  "Hai acquistato senza account? Inserisci l'email e il telefono usati al momento dell'ordine.": "Vous avez acheté sans compte ? Saisissez l'e-mail et le numéro de téléphone utilisés lors de la commande.",
  "Inserisci sia l'email sia il telefono usati per l'ordine.": "Saisissez l'e-mail et le numéro de téléphone utilisés pour la commande.",
  "Verifica che email e telefono coincidano con quelli usati al checkout.": "Vérifiez que votre e-mail et votre numéro de téléphone correspondent à ceux utilisés lors du paiement.",
  "Puoi ritrovare questo ordine in qualsiasi momento dalla tua area personale, anche dopo aver chiuso il browser.": "Vous pouvez retrouver cette commande à tout moment depuis votre espace personnel, même après avoir fermé le navigateur.",
  "Se ti registri e accedi come cliente, i tuoi prossimi acquisti compariranno automaticamente nella tua area personale.": "Si vous vous inscrivez et vous connectez en tant que client, vos prochains achats apparaîtront automatiquement dans votre espace personnel.",
