  "Il testo del contenuto è obbligatorio.": "Le texte du contenu est obligatoire.",
  "L'autore non può superare 120 caratteri.": "L'auteur ne peut pas dépasser 120 caractères.",
  "Il riassunto non può superare 400 caratteri.": "Le résumé ne peut pas dépasser 400 caractères.",
  "La descrizione deve essere testo.": "La description doit être du texte.",
  "Il luogo deve essere testo.": "L'emplacement doit être du texte.",
  "immagine_url deve essere testo.": "url_image doit être du texte.",
  "Offerta creata ma non leggibile dal pannello.": "Offre créée mais non lisible par le panel.",
  "Articoli e contenuti editoriali della città: storie, approfondimenti e notizie dal territorio.": "Articles et contenus éditoriaux de la ville : histoires, insights et actualités de la région.",
  "Non ci sono ancora notizie disponibili.": "Il n'y a pas encore de nouvelles disponibles.",
  "L'aggregatore raccoglie le notizie di Castrovillari periodicamente. Torna presto a trovarci.": "L'agrégateur collecte périodiquement les nouvelles de Castrovillari. Revenez nous rendre visite bientôt.",
  "Le notizie di Castrovillari raccolte automaticamente da fonti istituzionali e pubbliche: Comune, Provincia, Regione, Parco del Pollino e Protezione Civile.": "Actualités Castrovillari collectées automatiquement à partir de sources institutionnelles et publiques : municipalité, province, région, parc du Pollino et protection civile.",
  "Google News · Castrovillari": "Google Actualités · Castrovillari",
  "Google News · Castrovillari Comune": "Google Actualités · Municipalité de Castrovillari",
  "Radici Calabria collega produttori, trasformatori, distributori e consumatori: le filiere dei territori arrivano in città.": "Radici Calabria relie producteurs, transformateurs, distributeurs et consommateurs : les chaînes d'approvisionnement locales arrivent dans la ville.",
  "Una piattaforma che valorizza le produzioni, le imprese e le identità territoriali, collegando produttori, trasformatori, distributori e consumatori.": "Une plateforme qui valorise les productions, les entreprises et les identités territoriales, reliant producteurs, transformateurs, distributeurs et consommateurs.",
  "Le offerte e le promozioni dei produttori e dei negozi del territorio: prodotti in sconto selezionati tra le filiere locali.": "Offres et promotions des producteurs et commerces locaux : produits à prix réduits sélectionnés parmi les filières locales.",
  "Le migliori offerte dei negozi di Castrovillari": "Les meilleures offres des magasins à Castrovillari",
  "Le eccellenze di Castrovillari e del Pollino: cipolle bianche, mieli e prodotti tipici selezionati dalle filiere del territorio.": "L'excellence de Castrovillari et Pollino : oignons blancs, miel et produits typiques sélectionnés dans les filières locales.",
  "Scopri monumenti, musei, cultura, eventi, sapori e borghi nei dintorni di Castrovillari e del Parco Nazionale del Pollino.": "Découvrez les monuments, les musées, la culture, les événements, les saveurs et les villages dans les environs de Castrovillari et du parc national du Pollino.",
  "Non ci sono ancora prodotti in promozione. Esplora i negozi e le produzioni del territorio.": "Il n'y a pas encore de produits en promotion. Découvrez les commerces et produits locaux.",
  "Non ci sono ancora prodotti nella vetrina territoriale. Esplora i negozi e le produzioni del territorio.": "Il n'y a pas encore de produits dans la vitrine locale. Découvrez les commerces et produits locaux.",
  "Presto potrai trovare promozioni esclusive dai negozi della tua città.": "Bientôt, vous pourrez trouver des promotions exclusives dans les magasins de votre ville.",
  "I prodotti dei negozi locali saranno visibili qui appena disponibili.": "Les produits des commerces locaux seront visibles ici dès qu'ils seront disponibles.",
  "Aggiungi prodotti dalle filiere del territorio prima di procedere al checkout.": "Ajoutez des produits provenant de chaînes d'approvisionnement locales avant de procéder au paiement.",
  "Completa il tuo ordine su Radici Calabria: ritiro o spedizione dai produttori e dai negozi del territorio.": "Complétez votre commande sur Radici Calabria : retrait ou expédition auprès des producteurs et magasins locaux.",
  "Acquista senza account oppure accedi per usare i dati del tuo profilo.": "Achetez sans compte ou connectez-vous pour utiliser vos données de profil.",
  "Stai acquistando come ospite: non è richiesta la registrazione, compila i tuoi dati per l'ordine.": "Vous achetez en tant qu'invité : aucune inscription n'est requise, remplissez les détails de votre commande.",
  "Stai acquistando come ospite: non è richiesta la registrazione, indica solo chi ritira.": "Vous achetez en tant qu'invité : aucune inscription n'est requise, indiquez simplement qui récupère.",
  "Stai acquistando come ospite: compila i tuoi dati qui sotto. Non è richiesta la registrazione.": "Vous achetez en tant qu'invité : remplissez vos coordonnées ci-dessous. L'inscription n'est pas requise.",
  "Usiamo l'indirizzo del tuo profilo. Puoi cambiarlo solo per questo ordine senza modificare il profilo.": "Nous utilisons votre adresse de profil. Vous pouvez le modifier uniquement pour cette commande sans modifier le profil.",
  "Puoi cambiarlo solo per questo ordine senza modificare il profilo.": "Vous pouvez le modifier uniquement pour cette commande sans modifier le profil.",
  "Account Google autenticato. Completa solo i dati dell'attività per concludere la registrazione.": "Compte Google authentifié. Remplissez uniquement les détails de l'entreprise pour terminer l'inscription.",
  "Registrazione completata e accesso effettuato. Il tuo account è ora in attesa dell'approvazione dell'amministratore prima di poter utilizzare le aree personali della piattaforma.": "Inscription terminée et connecté. Votre compte est maintenant en attente de l'approbation de l'administrateur avant de pouvoir utiliser les espaces personnels de la plateforme.",
  "Ti abbiamo inviato una email di conferma della registrazione. Non devi fare altro: riceverai una nuova comunicazione quando l'amministratore avrà deciso.": "Nous vous avons envoyé un email confirmant votre inscription. Vous n'avez rien d'autre à faire : vous recevrez une nouvelle communication lorsque l'administrateur aura décidé.",
  "Ti abbiamo inviato un'email per confermare la registrazione. Clicca sul link contenuto nel messaggio per attivare il tuo account.": "Nous vous avons envoyé un email pour confirmer votre inscription. Cliquez sur le lien dans le message pour activer votre compte.",
  "Controlla la posta in arrivo e la cartella spam.": "Vérifiez votre boîte de réception et votre dossier spam.",
  "Non hai ricevuto il messaggio? Controlla la cartella spam o riprova tra qualche minuto.": "Vous n'avez pas reçu le message ? Veuillez vérifier votre dossier spam ou réessayer dans quelques minutes.",
  "Se l'account esiste e non è ancora confermato, ti abbiamo reinviato l'email di conferma. Controlla la posta in arrivo e la cartella spam.": "Si le compte existe et n'est pas encore confirmé, nous vous avons renvoyé l'e-mail de confirmation. Vérifiez votre boîte de réception et votre dossier spam.",
  "Link di recupero inviato. Apri il messaggio e segui le istruzioni.": "Lien de récupération envoyé. Ouvrez le message et suivez les instructions.",
