  "Stato richiesto: aperte, turno o tutte.": "Statut demandé : ouvert, shift ou tout.",
  "Cerca farmacie aperte, di turno o tutte.": "Recherchez les pharmacies ouvertes, de garde ou toutes.",
  "Ciao! Sono l'Assistente di LocalHub": "SALUT! Je suis l'assistant LocalHub",
  "Cerca offerte, promozioni e sconti attivi.": "Recherchez des offres actives, des promotions et des réductions.",
  "Cerca eventi, manifestazioni e appuntamenti.": "Recherchez des événements, des démonstrations et des rendez-vous.",
  "Cerca prodotti acquistabili nel catalogo locale.": "Recherchez des produits achetables dans le catalogue local.",
  "Restituisce il meteo aggiornato di Castrovillari.": "Renvoie la météo mise à jour de Castrovillari.",
  "Cerca negozi, attività, professionisti e servizi locali.": "Recherchez des commerces, des entreprises, des professionnels et des services locaux.",
  "Elenca le categorie del catalogo con il numero di negozi.": "Répertorie les catégories de catalogue avec le nombre de magasins.",
  "Cerca articoli e contenuti editoriali pubblicati su Radici Calabria.": "Recherchez des articles et du contenu éditorial publiés sur Radici Calabria.",
  "Chiedi qualcosa… es. farmacia aperta adesso, pizzeria in centro": "Demandez quelque chose… par ex. pharmacie ouverte maintenant, pizzeria au centre",
  "Cerca le ultime notizie pubblicate su Radici Calabria, con fonte e link.": "Recherchez les dernières nouvelles publiées sur Radici Calabria, avec source et lien.",
  "Cerca prodotti nelle categorie regalo; strumento interno al fan-out.": "Rechercher des produits dans les catégories cadeaux ; instrument interne à la sortance.",
  "Posso aiutarti a trovare negozi, servizi e attività locali. Dimmi cosa cerchi!": "Je peux vous aider à trouver des commerces, services et entreprises de proximité. Dites-moi ce que vous cherchez !",
  "Cerca trasversalmente negozi, prodotti, offerte, eventi, notizie, contenuti e categorie.": "Recherchez parmi les boutiques, les produits, les offres, les événements, les actualités, le contenu et les catégories.",
  "Sono il tuo assistente allo shopping su Radici Calabria. Posso aiutarti a trovare negozi, prodotti e servizi nella tua città.": "Je suis votre assistante commerciale sur Radici Calabria. Je peux vous aider à trouver des commerces, des produits et des services dans votre ville.",
  "La guida di Radici Calabria invita a scoprire le tradizioni gastronomiche di Castrovillari e del Pollino, compresa la Cipolla Bianca. La vetrina Eccellenze Calabresi mostra i prodotti effettivamente pubblicati dai negozi.": "Le guide Radici Calabria vous invite à découvrir les traditions gastronomiques de Castrovillari et Pollino, dont l'oignon blanc. La vitrine Eccellenze Calabresi présente les produits réellement édités par les magasins.",
