  "© 2026 Radici Calabria · Castrovillari · Privacy · Termini e condizioni": "© 2026 Radici Calabria · Castrovillari · Confidentialité · Termes et conditions",
  "Accesso negato. La verifica ha rilevato un'età inferiore ai 18 anni. Potrai riprovare dopo il periodo di blocco.": "Accès refusé. Le contrôle a révélé qu'il avait moins de 18 ans. Vous pourrez réessayer après la période de blocage.",
