  "Torrone di Bagnara IGP": "Nougat Bagnara IGP",
  "Pesca costiera tra Tirreno e Ionio, acquacoltura e tradizioni marinare: dalle marinerie di Scilla e Bagnara ai porti del Crotonese.": "Pêche côtière entre mers Tyrrhénienne et Ionienne, aquaculture et traditions maritimes : des marinas de Scilla et Bagnara aux ports de Crotone.",
  "Le marinerie dello Stretto lavorano pesce azzurro, alici e pesce spada con tecniche tramandate di padre in figlio; lungo lo Ionio l'acquacoltura alleva orate e branzini in mare aperto, in gabbie ancorate al largo.": "Les marinas du détroit traitent le poisson bleu, les anchois et l'espadon avec des techniques transmises de père en fils ; le long de la mer Ionienne, l'aquaculture élève des daurades et des bars en pleine mer, dans des cages ancrées au large.",
  "La filiera corta dei porti rifornisce pescherie e ristoranti con il pescato del giorno. Alici e sardine si conservano sott'olio o sotto sale, mentre il pesce spada si lavora a trancio già sulla banchina, tra ghiaccio e casse.": "La chaîne d’approvisionnement courte dans les ports approvisionne les poissonneries et les restaurants en pêche du jour. Les anchois et les sardines sont conservés dans l'huile ou le sel, tandis que l'espadon est tranché directement sur le quai, entre glace et caisses.",
  "Pesca costiera notturna o all'alba, con reti e palangari": "Pêche côtière de nuit ou à l'aube, avec filets et palangres",
  "Selezione e ghiaccio a bordo, poi asta del pesce al porto": "Sélection et glace à bord, puis criée au port",
  "Conservazione sott'olio, sotto sale o abbattimento per il fresco": "Conservation dans l'huile, le sel ou le refroidissement rapide pour un stockage au frais",
  "Pesce azzurro soprattutto in primavera ed estate; pesce spada da maggio a settembre.": "Poisson bleu surtout au printemps et en été ; l'espadon de mai à septembre.",
