  "Per informazioni sui negozi, sui prodotti o sul funzionamento della piattaforma scrivici: ti rispondiamo il prima possibile.": "Pour obtenir des informations sur les boutiques, les produits ou le fonctionnement de la plateforme, écrivez-nous : nous vous répondrons dans les plus brefs délais.",
  "Per un problema relativo a un ordine specifico, contatta prima il Venditore attraverso i recapiti indicati nella scheda del negozio o dell'ordine. Per il supporto tecnico sulla piattaforma puoi scriverci": "Pour un problème relatif à une commande spécifique, contactez au préalable le Vendeur via les coordonnées indiquées dans la boutique ou le bon de commande. Pour un support technique sur la plateforme vous pouvez nous écrire",
