  "La società [Inserisci Nome Azienda/Ditta] (di seguito, il “Gestore”) mette a disposizione degli utenti una piattaforma tecnologica web e i relativi servizi digitali e di comunicazione (di seguito, il “Sito” o la “Piattaforma”), finalizzati a consentire l'incontro, l'interazione e la conclusione di rapporti commerciali tra venditori indipendenti (di seguito, i “Venditori”) e potenziali acquirenti (di seguito, gli “Acquirenti”).": "La société [Insérer le nom de la société/de la société] (ci-après, le « Gérant ») met à la disposition des utilisateurs une plateforme technologique web et les services numériques et de communication associés (ci-après, le « Site » ou la « Plateforme »), visant à permettre la rencontre, l'interaction et la conclusion de relations commerciales entre des vendeurs indépendants (ci-après, les « Vendeurs ») et des acheteurs potentiels (ci-après, les « Acheteurs »).",
