  ": la piattaforma e l'infrastruttura tecnologica gestita da [Inserisci Nome Azienda/Ditta].": ": la plateforme et l'infrastructure technologique gérées par [Insérer le nom de l'entreprise].",
  ": la proposta relativa a un prodotto, servizio o prestazione pubblicata dal Venditore.": ": la proposition relative à un produit, un service ou une prestation publiée par le Vendeur.",
  ": la richiesta del Cliente relativa a un'offerta, secondo il flusso applicabile.": ": la demande d'offre du Client, selon le flux applicable.",
  ": la richiesta di acquisto o prenotazione riferita a un'offerta del venditore, secondo il flusso applicabile.": ": la demande d'achat ou de réservation faisant référence à une offre du vendeur, selon le flux applicable.",
  ": lo spazio o profilo del Venditore pubblicato sulla piattaforma.": ": l'espace ou le profil du Vendeur publié sur la plateforme.",
  "Il Gestore non acquista, non rivende e non commercializza in proprio i prodotti o i servizi offerti dai Venditori.": "Le Gestionnaire n’achète, ne revend ni ne commercialise lui-même les produits ou services proposés par les Vendeurs.",
  "Il trattamento dei dati personali avviene secondo l'Informativa Privacy di Radici Calabria e la normativa applicabile, incluso il Regolamento (UE) 2016/679 (GDPR). Ciascun utente professionale opera quale autonomo titolare del trattamento per i dati trattati nell'ambito delle proprie attività, nei limiti e secondo le rispettive responsabilità previste dalla normativa applicabile.": "Le traitement des données personnelles a lieu conformément à la politique de confidentialité de Radici Calabria et à la législation applicable, y compris le règlement (UE) 2016/679 (RGPD). Chaque utilisateur professionnel agit en qualité de responsable de traitement indépendant pour les données traitées dans le cadre de ses activités, dans les limites et selon les responsabilités respectives fixées par la législation applicable.",
  "La Piattaforma integra e utilizza servizi, contenuti e strumenti informativi forniti da soggetti terzi, inclusi i componenti e i widget informativi resi disponibili all'interno della Piattaforma. I dati, le informazioni, gli aggiornamenti e i risultati visualizzati attraverso tali componenti sono forniti e gestiti dai rispettivi soggetti o servizi di origine. La responsabilità dell'esattezza, completezza, aggiornamento, disponibilità e continuità di tali dati e informazioni è a carico del relativo soggetto o servizio di origine, secondo le proprie condizioni e responsabilità. Radici Calabria non modifica né garantisce autonomamente tali dati e non assume responsabilità per eventuali inesattezze, ritardi, omissioni, indisponibilità o interruzioni imputabili al servizio o al soggetto che li fornisce, fatti salvi gli obblighi inderogabili previsti dalla legge.": "La Plateforme intègre et utilise des services, contenus et outils d'information fournis par des tiers, y compris les composants et widgets d'informations mis à disposition au sein de la Plateforme. Les données, informations, mises à jour et résultats affichés via ces composants sont fournis et conservés par leurs entités ou services d'origine respectifs. La responsabilité de l'exactitude, de l'exhaustivité, de la mise à jour, de la disponibilité et de la continuité de ces données et informations incombe à l'entité ou au service d'origine concerné, selon ses propres conditions et responsabilités. Radici Calabria ne modifie ni ne garantit ces données de manière indépendante et n'assume aucune responsabilité pour les inexactitudes, retards, omissions, indisponibilités ou interruptions imputables au service ou à la personne qui le fournit, sans préjudice des obligations impératives établies par la loi.",
  "aggiornare offerte, prezzi e disponibilità;": "mettre à jour les offres, les prix et la disponibilité ;",
  "collaborare alle verifiche tecniche e documentali;": "collaborer aux contrôles techniques et documentaires ;",
  "gestire gli ordini e le comunicazioni in modo tempestivo;": "gérer les commandes et les communications en temps opportun ;",
