  "Confettura di bergamotto, prodotto dimostrativo nella selezione delle eccellenze.": "Confiture de bergamote, produit de démonstration dans la sélection d'excellence.",
  "Miele aromatizzato al bergamotto, prodotto dimostrativo nella selezione delle eccellenze.": "Miel aromatisé à la bergamote, produit de démonstration dans la sélection d'excellence.",
